<?php
/**
 * Tests for EnableMediaReplace\Controller\ReplaceController
 * (classes/Controller/ReplaceController.php).
 *
 * Every test works on real attachments uploaded from copies of the fixtures
 * in tests/fixtures/ into the test install's uploads folder, with metadata
 * generated by WordPress. The protected and private steps (setupTarget(),
 * getNewTargetLocation(), getTargetURL(), updateDate(), removeCurrent(),
 * normalizePath()) are reached by reflection; run() is called directly.
 *
 * Snapshot/restore: the current user (an administrator for the run), the
 * `timezone_string` / `gmt_offset` options, every filter and action a test
 * adds, the attachments created (deleted with their files), and every file,
 * directory and symlink a test creates. Nothing in this class talks HTTP;
 * a fail-fast `pre_http_request` filter at priority 9999 refuses and records
 * any request, and tear_down() asserts none was made.
 *
 * @package Enable_Media_Replace
 */

use EnableMediaReplace\Controller\ReplaceController;
use EnableMediaReplace\FileSystem\Model\File\FileModel;

class ReplaceControllerTest extends WP_UnitTestCase {

	/**
	 * @var int
	 */
	private $admin_id;

	/**
	 * @var int
	 */
	private $saved_user;

	/**
	 * @var array<string,mixed>
	 */
	private $saved_options = array();

	/**
	 * Attachments to delete in tear_down().
	 *
	 * @var int[]
	 */
	private $attachments = array();

	/**
	 * Files and symlinks to delete in tear_down().
	 *
	 * @var string[]
	 */
	private $files = array();

	/**
	 * Directories to remove in tear_down() (deepest last added, removed in reverse).
	 *
	 * @var string[]
	 */
	private $dirs = array();

	/**
	 * Hooks added by a test: array( hook, callback, priority ).
	 *
	 * @var array
	 */
	private $hooks = array();

	/**
	 * URLs refused by the fail-fast filter.
	 *
	 * @var string[]
	 */
	private $blocked = array();

	/**
	 * Events recorded by the hook spies.
	 *
	 * @var array
	 */
	private $events = array();

	public function set_up() {
		parent::set_up();
		$this->saved_user = get_current_user_id();
		foreach ( array( 'timezone_string', 'gmt_offset' ) as $option ) {
			$this->saved_options[ $option ] = get_option( $option, null );
		}
		$this->admin_id = self::factory()->user->create( array( 'role' => 'administrator' ) );
		wp_set_current_user( $this->admin_id );
		$this->blocked = array();
		$this->events  = array();
		add_filter( 'pre_http_request', array( $this, 'fail_fast' ), 9999, 3 );
	}

	public function tear_down() {
		remove_filter( 'pre_http_request', array( $this, 'fail_fast' ), 9999 );
		foreach ( $this->hooks as $hook ) {
			remove_filter( $hook[0], $hook[1], $hook[2] );
		}
		$this->hooks = array();

		foreach ( $this->attachments as $id ) {
			wp_delete_attachment( $id, true );
		}
		$this->attachments = array();
		foreach ( $this->files as $file ) {
			if ( is_link( $file ) || file_exists( $file ) ) {
				if ( is_dir( $file ) && ! is_link( $file ) ) {
					continue;
				}
				unlink( $file );
			}
		}
		$this->files = array();
		foreach ( array_reverse( $this->dirs ) as $dir ) {
			if ( is_dir( $dir ) ) {
				$this->remove_tree( $dir );
			}
		}
		$this->dirs = array();

		foreach ( $this->saved_options as $option => $value ) {
			if ( null === $value ) {
				delete_option( $option );
			} else {
				update_option( $option, $value );
			}
		}
		wp_set_current_user( $this->saved_user );

		$blocked       = $this->blocked;
		$this->blocked = array();
		parent::tear_down();
		$this->assertSame( array(), $blocked, 'A request reached the fail-fast filter.' );
	}

	/**
	 * Refuses and records every HTTP request nothing else answered.
	 */
	public function fail_fast( $preempt, $args, $url ) {
		if ( false !== $preempt ) {
			return $preempt;
		}
		$this->blocked[] = $url;
		return new WP_Error( 'http_blocked', 'Blocked unmocked request to ' . $url );
	}

	/*
	 * Helpers.
	 */

	private function fixture( $name ) {
		return dirname( __DIR__ ) . '/fixtures/' . $name;
	}

	private function add_hook( $hook, $callback, $priority = 10, $args = 1 ) {
		add_filter( $hook, $callback, $priority, $args );
		$this->hooks[] = array( $hook, $callback, $priority );
	}

	private function remove_tree( $dir ) {
		$items = scandir( $dir );
		foreach ( $items as $item ) {
			if ( '.' === $item || '..' === $item ) {
				continue;
			}
			$path = $dir . '/' . $item;
			if ( is_dir( $path ) && ! is_link( $path ) ) {
				$this->remove_tree( $path );
			} else {
				unlink( $path );
			}
		}
		rmdir( $dir );
	}

	/**
	 * Uploads a copy of a fixture as a new attachment with generated metadata.
	 */
	private function upload( $fixture = 'test-image.jpg', $name = null ) {
		$copy_dir = get_temp_dir() . 'emr-rc-' . wp_generate_password( 8, false, false );
		wp_mkdir_p( $copy_dir );
		$this->dirs[] = $copy_dir;
		$copy         = $copy_dir . '/' . ( null === $name ? $fixture : $name );
		copy( $this->fixture( $fixture ), $copy );
		$id                  = self::factory()->attachment->create_upload_object( $copy );
		$this->attachments[] = $id;
		return $id;
	}

	/**
	 * A temporary "uploaded" file, as UploadViewController hands it over.
	 */
	private function tmp_upload( $fixture = 'test-image.jpg' ) {
		$tmp = wp_tempnam( 'emr-upload' );
		copy( $this->fixture( $fixture ), $tmp );
		$this->files[] = $tmp;
		return $tmp;
	}

	/**
	 * Writes a solid-colour JPEG of the given size with GD and returns its path.
	 */
	private function make_jpeg( $path, $width, $height ) {
		if ( ! function_exists( 'imagecreatetruecolor' ) ) {
			$this->markTestSkipped( 'GD is needed to generate test images of a given size.' );
		}
		$image = imagecreatetruecolor( $width, $height );
		imagefilledrectangle( $image, 0, 0, $width - 1, $height - 1, imagecolorallocate( $image, 30, 120, 200 ) );
		imagejpeg( $image, $path, 80 );
		if ( PHP_VERSION_ID < 80000 ) {
			// GD images are objects since PHP 8.0; imagedestroy() is a no-op there and deprecated since 8.5.
			imagedestroy( $image );
		}
		return $path;
	}

	/**
	 * A temporary "uploaded" JPEG with other bytes and dimensions than test-image.jpg.
	 */
	private function tmp_small_jpeg( $width = 120, $height = 90 ) {
		$tmp           = wp_tempnam( 'emr-upload' );
		$this->files[] = $tmp;
		return $this->make_jpeg( $tmp, $width, $height );
	}

	/**
	 * Uploads a generated 400x300 JPEG, large enough for WordPress to
	 * create thumbnail and medium sizes.
	 */
	private function upload_large() {
		$copy_dir = get_temp_dir() . 'emr-rc-' . wp_generate_password( 8, false, false );
		wp_mkdir_p( $copy_dir );
		$this->dirs[] = $copy_dir;
		$file         = $this->make_jpeg( $copy_dir . '/emr-large.jpg', 400, 300 );
		$id           = self::factory()->attachment->create_upload_object( $file );
		$this->attachments[] = $id;
		return $id;
	}

	/**
	 * Default setupParams() arguments, merged with $overrides.
	 */
	private function params( array $overrides = array() ) {
		return array_merge(
			array(
				'replace_type'      => 'replace',
				'new_location'      => false,
				'location_dir'      => null,
				'timestamp_replace' => ReplaceController::TIME_UPDATEMODIFIED,
				'new_date'          => current_time( 'mysql' ),
				'new_filename'      => 'test-image.jpg',
				'uploadFile'        => '',
			),
			$overrides
		);
	}

	private function prop( $object, $name ) {
		$ref = new ReflectionProperty( ReplaceController::class, $name );
		$ref->setAccessible( true );
		return $ref->getValue( $object );
	}

	private function set_prop( $object, $name, $value ) {
		$ref = new ReflectionProperty( ReplaceController::class, $name );
		$ref->setAccessible( true );
		$ref->setValue( $object, $value );
	}

	private function call( $object, $method, array $args = array() ) {
		$ref = new ReflectionMethod( ReplaceController::class, $method );
		$ref->setAccessible( true );
		return $ref->invokeArgs( $object, $args );
	}

	/**
	 * A directory under the uploads basedir, removed in tear_down().
	 */
	private function uploads_subdir( $relative ) {
		$uploads = wp_upload_dir();
		$dir     = $uploads['basedir'] . '/' . $relative;
		wp_mkdir_p( $dir );
		$this->dirs[] = $uploads['basedir'] . '/' . strtok( $relative, '/' );
		return $dir;
	}

	/**
	 * An attachment whose attached file is a `-scaled` copy, with
	 * `original_image` in its metadata, as WordPress 5.3+ writes it.
	 *
	 * @return array( id, original path, scaled path )
	 */
	private function scaled_attachment() {
		$uploads = wp_upload_dir();
		$base    = 'emr-big-' . strtolower( wp_generate_password( 6, false, false ) );
		$orig    = $uploads['path'] . '/' . $base . '.jpg';
		$scaled  = $uploads['path'] . '/' . $base . '-scaled.jpg';
		copy( $this->fixture( 'test-image.jpg' ), $orig );
		copy( $this->fixture( 'test-image.jpg' ), $scaled );
		$this->files[] = $orig;
		$this->files[] = $scaled;

		$id = self::factory()->attachment->create_object(
			array(
				'file'           => $scaled,
				'post_mime_type' => 'image/jpeg',
				'post_title'     => $base,
			)
		);
		$this->attachments[] = $id;
		$size                = getimagesize( $scaled );
		wp_update_attachment_metadata(
			$id,
			array(
				'width'          => $size[0],
				'height'         => $size[1],
				'file'           => _wp_relative_upload_path( $scaled ),
				'sizes'          => array(),
				'original_image' => $base . '.jpg',
			)
		);
		return array( $id, $orig, $scaled );
	}

	private function record( $name ) {
		$events = &$this->events;
		return function () use ( $name, &$events ) {
			$events[] = array( $name, func_get_args() );
			$args     = func_get_args();
			return isset( $args[0] ) ? $args[0] : null;
		};
	}

	private function event_names() {
		return array_map(
			function ( $event ) {
				return $event[0];
			},
			$this->events
		);
	}

	/*
	 * Constructor and getSourceFile().
	 */

	public function test_constructor_resolves_the_attached_file_as_a_file_model() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$source = $controller->getSourceFile();
		$this->assertInstanceOf( FileModel::class, $source );
		$this->assertSame( get_attached_file( $id ), $source->getFullPath() );
		$this->assertTrue( $source->exists() );
	}

	public function test_get_source_file_untranslated_is_the_same_file_when_nothing_was_translated() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$this->assertNull( $this->prop( $controller, 'sourceFileUntranslated' ) );
		$this->assertSame( $controller->getSourceFile(), $controller->getSourceFile( true ) );
		$this->assertSame( $controller->getSourceFile(), $controller->getSourceFile( false ) );
	}

	public function test_virtual_source_is_translated_and_the_untranslated_file_is_kept() {
		$id     = $this->upload();
		$local  = get_attached_file( $id );
		$remote = 'https://cdn.example.test/bucket/' . wp_basename( $local );
		$seen   = array();

		$this->add_hook(
			'emr/replace/original_image_path',
			function () use ( $remote ) {
				return $remote;
			}
		);
		$this->add_hook(
			'emr/file/virtual/translate',
			function ( $path, $file, $post_id ) use ( $local, &$seen ) {
				$seen = array( $path, $file, $post_id );
				return $local;
			},
			10,
			3
		);

		$controller = new ReplaceController( $id );

		$this->assertSame( $local, $controller->getSourceFile()->getFullPath() );
		$untranslated = $controller->getSourceFile( true );
		$this->assertInstanceOf( FileModel::class, $untranslated );
		$this->assertNotSame( $controller->getSourceFile(), $untranslated );
		$this->assertSame( $remote, $untranslated->getRawFullPath() );
		$this->assertTrue( $untranslated->is_virtual() );
		$this->assertSame( $id, $seen[2] );
		$this->assertInstanceOf( FileModel::class, $seen[1] );
	}

	public function test_virtual_source_without_a_translation_stays_virtual() {
		$id     = $this->upload();
		$remote = 'https://cdn.example.test/bucket/remote-only.jpg';
		$this->add_hook(
			'emr/replace/original_image_path',
			function () use ( $remote ) {
				return $remote;
			}
		);

		$controller = new ReplaceController( $id );

		$this->assertTrue( $controller->getSourceFile()->is_virtual() );
		$this->assertSame( $remote, $controller->getSourceFile()->getRawFullPath() );
		$this->assertSame( $remote, $controller->getSourceFile( true )->getRawFullPath() );
	}

	public function test_scaled_attachment_uses_the_original_image_as_source() {
		list( $id, $orig, $scaled ) = $this->scaled_attachment();
		$this->assertSame( $scaled, get_attached_file( $id ), 'Sentinel: the attached file is the -scaled copy.' );

		$controller = new ReplaceController( $id );

		$this->assertSame( $orig, $controller->getSourceFile()->getFullPath() );
	}

	public function test_relative_attached_path_is_prefixed_with_the_uploads_basedir() {
		$id       = $this->upload();
		$absolute = get_attached_file( $id );
		$relative = get_post_meta( $id, '_wp_attached_file', true );
		$this->assertNotSame( '/', $relative[0], 'Sentinel: the stored path is relative.' );

		$this->add_hook( 'emr_unfiltered_get_attached_file', '__return_false' );
		$this->add_hook(
			'get_attached_file',
			function () use ( $relative ) {
				return $relative;
			}
		);

		$controller = new ReplaceController( $id );

		$uploads = wp_get_upload_dir();
		$path    = $controller->getSourceFile()->getFullPath();
		$this->assertSame( '/', $path[0] );
		$this->assertSame( $uploads['basedir'] . '/' . $relative, $path );
		$this->assertSame( $absolute, $path );
	}

	public function test_original_image_path_filter_receives_the_path_and_post_id() {
		$id    = $this->upload();
		$other = $this->upload( 'codeispoetry.png' );
		$seen  = array();
		$this->add_hook(
			'emr/replace/original_image_path',
			function ( $path, $post_id ) use ( $other, &$seen ) {
				$seen = array( $path, $post_id );
				return get_attached_file( $other );
			},
			10,
			2
		);

		$controller = new ReplaceController( $id );

		$this->assertSame( array( get_attached_file( $id ), $id ), $seen );
		$this->assertSame( get_attached_file( $other ), $controller->getSourceFile()->getFullPath() );
	}

	public function test_original_image_path_false_falls_back_to_the_attached_file() {
		$id = $this->upload();
		$this->add_hook( 'emr/replace/original_image_path', '__return_false' );

		$controller = new ReplaceController( $id );

		$this->assertSame( get_attached_file( $id ), $controller->getSourceFile()->getFullPath() );
	}

	public function test_non_image_attachment_uses_the_attached_file() {
		$id = $this->upload( 'test-vector.svg', 'emr-doc.txt' );

		$controller = new ReplaceController( $id );

		$this->assertFalse( wp_get_original_image_path( $id ), 'Sentinel: not an image.' );
		$this->assertSame( get_attached_file( $id ), $controller->getSourceFile()->getFullPath() );
	}

	/*
	 * setupParams().
	 */

	public function test_setup_params_replace_selects_mode_replace_and_returns_true() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$result = $controller->setupParams( $this->params() );

		$this->assertTrue( $result );
		$this->assertSame( ReplaceController::MODE_REPLACE, $this->prop( $controller, 'replaceType' ) );
		$this->assertInstanceOf( FileModel::class, $this->prop( $controller, 'targetFile' ) );
		$this->assertNull( $controller->returnLastError() );
	}

	public function test_setup_params_replace_and_search_selects_mode_searchreplace() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$this->assertTrue( $controller->setupParams( $this->params( array( 'replace_type' => 'replace_and_search', 'new_filename' => 'emr-renamed.jpg' ) ) ) );

		$this->assertSame( ReplaceController::MODE_SEARCHREPLACE, $this->prop( $controller, 'replaceType' ) );
	}

	/**
	 * @dataProvider provide_other_replace_types
	 */
	public function test_setup_params_any_other_replace_type_selects_mode_replace( $type ) {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$controller->setupParams( $this->params( array( 'replace_type' => $type ) ) );

		$this->assertSame( ReplaceController::MODE_REPLACE, $this->prop( $controller, 'replaceType' ) );
	}

	public function provide_other_replace_types() {
		return array(
			'integer 2'       => array( 2 ),
			'false'           => array( false ),
			'upper case'      => array( 'REPLACE_AND_SEARCH' ),
			'padded'          => array( ' replace_and_search' ),
			'empty string'    => array( '' ),
		);
	}

	public function test_setup_params_stores_the_request_values() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );
		$tmp        = $this->tmp_upload();

		$controller->setupParams(
			$this->params(
				array(
					'timestamp_replace' => ReplaceController::TIME_CUSTOM,
					'new_date'          => '2021-02-03 04:05:06',
					'new_filename'      => 'Ünïcode name.jpg',
					'uploadFile'        => $tmp,
				)
			)
		);

		$this->assertSame( ReplaceController::TIME_CUSTOM, $this->prop( $controller, 'timeMode' ) );
		$this->assertSame( '2021-02-03 04:05:06', $this->prop( $controller, 'newDate' ) );
		$this->assertSame( 'Ünïcode name.jpg', $this->prop( $controller, 'new_filename' ) );
		$this->assertSame( $tmp, $this->prop( $controller, 'tmpUploadPath' ) );
	}

	public function test_setup_params_takes_the_new_location_in_search_replace_mode() {
		$id = $this->upload();
		$this->uploads_subdir( 'emr-loc-a/inner' );
		$controller = new ReplaceController( $id );

		$controller->setupParams(
			$this->params(
				array(
					'replace_type' => 'replace_and_search',
					'new_location' => true,
					'location_dir' => 'emr-loc-a/inner',
					'new_filename' => 'emr-moved.jpg',
				)
			)
		);

		$this->assertSame( 'emr-loc-a/inner', $this->prop( $controller, 'new_location' ) );
	}

	public function test_setup_params_ignores_the_new_location_in_replace_mode() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$controller->setupParams( $this->params( array( 'new_location' => true, 'location_dir' => 'emr-loc-b' ) ) );

		$this->assertNull( $this->prop( $controller, 'new_location' ) );
		$this->assertSame( get_attached_file( $id ), $this->prop( $controller, 'targetFile' )->getFullPath() );
	}

	public function test_setup_params_ignores_the_new_location_unless_it_is_exactly_true() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$controller->setupParams(
