				array(
					'replace_type' => 'replace_and_search',
					'new_location' => '1',
					'location_dir' => 'emr-loc-c',
					'new_filename' => 'emr-x.jpg',
				)
			)
		);

		$this->assertNull( $this->prop( $controller, 'new_location' ) );
	}

	public function test_setup_params_ignores_the_new_location_without_a_directory() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$controller->setupParams(
			$this->params(
				array(
					'replace_type' => 'replace_and_search',
					'new_location' => true,
					'location_dir' => null,
					'new_filename' => 'emr-x.jpg',
				)
			)
		);

		$this->assertNull( $this->prop( $controller, 'new_location' ) );
