	public function test_last_error_defaults_to_null_and_an_empty_array() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$this->assertNull( $controller->returnLastError() );
		$this->assertSame( array(), $controller->returnLastErrorData() );
	}

	/*
	 * setupTarget(), through setupParams().
	 */

	public function test_replace_mode_targets_the_source_path() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );

		$controller->setupParams( $this->params( array( 'new_filename' => 'something-else.jpg' ) ) );

		$this->assertSame( $controller->getSourceFile()->getFullPath(), $this->prop( $controller, 'targetFile' )->getFullPath() );
	}

	public function test_search_replace_with_a_new_name_targets_the_source_directory() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );
		$name       = 'emr-new-' . strtolower( wp_generate_password( 6, false, false ) ) . '.jpg';

		$controller->setupParams( $this->params( array( 'replace_type' => 'replace_and_search', 'new_filename' => $name ) ) );

		$this->assertSame( dirname( get_attached_file( $id ) ) . '/' . $name, $this->prop( $controller, 'targetFile' )->getFullPath() );
	}

	public function test_search_replace_makes_a_clashing_name_unique() {
		$id      = $this->upload();
		$dir     = dirname( get_attached_file( $id ) );
		$name    = 'emr-clash-' . strtolower( wp_generate_password( 6, false, false ) );
		$clashes = $dir . '/' . $name . '.jpg';
		copy( $this->fixture( 'test-image.jpg' ), $clashes );
		$this->files[] = $clashes;
		$controller    = new ReplaceController( $id );

		$controller->setupParams( $this->params( array( 'replace_type' => 'replace_and_search', 'new_filename' => $name . '.jpg' ) ) );

		$this->assertSame( $dir . '/' . $name . '-1.jpg', $this->prop( $controller, 'targetFile' )->getFullPath() );
	}

	/**
	 * setupTarget() means to fall back to MODE_REPLACE when the computed
	 * search-replace target equals the source path and name, but the line
	 * `$this->replaceType == self::MODE_REPLACE;` is a comparison, not an
	 * assignment, so the mode stays MODE_SEARCHREPLACE and run() still
	 * rewrites the title, slug and GUID and runs the full search and
	 * replace. The file name itself is kept, as documented.
	 *
	 * How to recognise the fix: replaceType reads MODE_REPLACE (1) after
	 * setupParams() and the assertSame on MODE_SEARCHREPLACE (2) fails.
	 */
	public function test_same_name_and_path_keeps_search_replace_mode_pinned_for_deferred_fix() {
		$id         = $this->upload();
		$source     = get_attached_file( $id );
		$controller = new ReplaceController( $id );

		$result = $controller->setupParams( $this->params( array( 'replace_type' => 'replace_and_search', 'new_filename' => wp_basename( $source ) ) ) );

		$this->assertTrue( $result );
		$this->assertSame( $source, $this->prop( $controller, 'targetFile' )->getFullPath(), 'The source name is kept, without a -1 suffix.' );
		$this->assertSame( 2, ReplaceController::MODE_SEARCHREPLACE );
		$this->assertSame( ReplaceController::MODE_SEARCHREPLACE, $this->prop( $controller, 'replaceType' ), 'Pinned: the mode is not switched to MODE_REPLACE.' );
	}

