	/**
	 * normalizePath() drops `..` segments instead of resolving them, so a
	 * traversal attempt is folded back into the uploads folder (documented
	 * on getNewTargetLocation()): no ERROR_DIRECTORY_SECURITY, the target
	 * stays under the basedir.
	 *
	 * @dataProvider provide_traversal_locations
	 */
	public function test_traversal_locations_are_folded_into_the_uploads_folder( $location, $expected_relative ) {
		$id         = $this->upload();
		$uploads    = wp_upload_dir();
		$controller = new ReplaceController( $id );

		$result = $controller->setupParams(
			$this->params(
				array(
					'replace_type' => 'replace_and_search',
					'new_location' => true,
					'location_dir' => $location,
					'new_filename' => 'emr-escape.jpg',
				)
			)
		);

		$this->assertTrue( $result );
		$this->assertNull( $controller->returnLastError() );
		$target = $this->prop( $controller, 'targetFile' )->getFullPath();
		$this->assertSame( 0, strpos( $target, trailingslashit( $uploads['basedir'] ) ) );
		$this->assertSame( trailingslashit( $uploads['basedir'] ) . $expected_relative . 'emr-escape.jpg', $target );
	}

	public function provide_traversal_locations() {
		return array(
			'one level up'   => array( '../', '' ),
			'two levels up'  => array( '../../emr-out', 'emr-out/' ),
			'absolute path'  => array( '/etc', 'etc/' ),
			'mixed segments' => array( 'emr-a/../../emr-b/./', 'emr-a/emr-b/' ),
		);
	}

	public function test_directory_security_error_carries_path_and_basedir() {
		$id      = $this->upload();
		$uploads = wp_upload_dir();
		$real    = $uploads['basedir'];
		// The same directory spelled through a sibling and a `..` segment:
		// realpath() resolves it, normalizePath() drops the `..` and keeps
		// the sibling's name, so the prefixes differ.
		$sibling = dirname( $real ) . '/emr-alias-' . strtolower( wp_generate_password( 6, false, false ) );
		mkdir( $sibling );
		$this->dirs[] = $sibling;
		$alias        = $sibling . '/../' . basename( $real );
		$this->add_hook(
			'upload_dir',
			function ( $dirs ) use ( $alias ) {
				$dirs['basedir'] = $alias;
				return $dirs;
			}
		);
		$controller = new ReplaceController( $id );

		$result = $controller->setupParams(
			$this->params(
				array(
					'replace_type' => 'replace_and_search',
					'new_filename' => 'emr-any.jpg',
				)
			)
		);

		$this->assertFalse( $result );
		$this->assertSame( ReplaceController::ERROR_DIRECTORY_SECURITY, $controller->returnLastError() );
		$data = $controller->returnLastErrorData();
		$this->assertSame( array( 'path', 'basedir' ), array_keys( $data ) );
		$this->assertSame( trailingslashit( $real ), $data['basedir'] );
		$this->assertIsString( $data['path'] );
	}

