	/**
	 * getTargetURL() checks `strpos($url, '://') >= 0`, which is true for a
	 * URL without a scheme as well (false >= 0), so a relative attachment
	 * URL whose basename matches the target is returned as it is, and the
	 * "relative path" branch that would build an absolute URL from the
	 * uploads baseurl is never reached in that case. The check should be
	 * `!== false`.
	 *
	 * How to recognise the fix: the result becomes the absolute baseurl
	 * form and the assertSame on the relative URL fails.
	 */
	public function test_relative_attachment_url_is_returned_as_is_pinned_for_deferred_fix() {
		$id         = $this->upload();
		$controller = new ReplaceController( $id );
		$controller->setupParams( $this->params() );
		$this->add_hook(
			'wp_get_attachment_url',
			function ( $url ) {
				return wp_make_link_relative( $url );
			}
		);
		$relative = wp_get_attachment_url( $id );
		$this->assertFalse( strpos( $relative, '://' ), 'Sentinel: the attachment URL is relative.' );

		$result = $this->call( $controller, 'getTargetURL' );

		$this->assertIsString( $result );
		$this->assertSame( $relative, $result, 'Pinned: the relative URL comes back unchanged.' );
		$this->assertStringStartsWith( '/', $result );
	}

	/*
	 * updateDate().
	 */

	private function dates( $id ) {
		global $wpdb;
		return $wpdb->get_row( $wpdb->prepare( "SELECT post_date, post_date_gmt, post_modified, post_modified_gmt FROM {$wpdb->posts} WHERE ID = %d", $id ), ARRAY_A );
	}

	private function run_update_date( $id, $mode, $date ) {
		$controller = new ReplaceController( $id );
		$this->set_prop( $controller, 'timeMode', $mode );
		$this->set_prop( $controller, 'newDate', $date );
		$this->call( $controller, 'updateDate' );
	}

	/**
	 * @dataProvider provide_full_date_modes
	 */
	public function test_update_date_sets_all_four_dates( $mode ) {
		update_option( 'timezone_string', 'UTC' );
		$id = $this->upload();

		$this->run_update_date( $id, $mode, '2020-05-06 07:08:09' );

		$this->assertSame(
			array(
				'post_date'         => '2020-05-06 07:08:09',
				'post_date_gmt'     => '2020-05-06 07:08:09',
				'post_modified'     => '2020-05-06 07:08:09',
				'post_modified_gmt' => '2020-05-06 07:08:09',
			),
			$this->dates( $id )
		);
	}

	public function provide_full_date_modes() {
		return array(
			'update all' => array( ReplaceController::TIME_UPDATEALL ),
			'custom'     => array( ReplaceController::TIME_CUSTOM ),
		);
	}

	public function test_update_modified_keeps_the_post_date() {
		update_option( 'timezone_string', 'UTC' );
		$id     = $this->upload();
		$before = $this->dates( $id );
		$this->assertNotSame( '2019-01-02 03:04:05', $before['post_date'] );

		$this->run_update_date( $id, ReplaceController::TIME_UPDATEMODIFIED, '2019-01-02 03:04:05' );

		$after = $this->dates( $id );
		$this->assertSame( $before['post_date'], $after['post_date'] );
		$this->assertSame( $before['post_date_gmt'], $after['post_date_gmt'] );
		$this->assertSame( '2019-01-02 03:04:05', $after['post_modified'] );
		$this->assertSame( '2019-01-02 03:04:05', $after['post_modified_gmt'] );
	}

	/**
	 * @dataProvider provide_bucharest_dates
	 */
	public function test_update_date_converts_to_gmt_with_the_site_timezone( $local, $gmt ) {
		update_option( 'timezone_string', 'Europe/Bucharest' );
		$id = $this->upload();

		$this->run_update_date( $id, ReplaceController::TIME_CUSTOM, $local );

		$dates = $this->dates( $id );
		$this->assertSame( $local, $dates['post_date'] );
		$this->assertSame( $gmt, $dates['post_date_gmt'] );
		$this->assertSame( $gmt, $dates['post_modified_gmt'] );
	}

	public function provide_bucharest_dates() {
		return array(
			'winter, UTC+2' => array( '2024-01-15 12:00:00', '2024-01-15 10:00:00' ),
			'summer, UTC+3' => array( '2024-07-15 12:00:00', '2024-07-15 09:00:00' ),
		);
	}

	public function test_update_date_clears_the_post_cache() {
		update_option( 'timezone_string', 'UTC' );
		$id = $this->upload();
		get_post( $id );
		$this->assertNotFalse( wp_cache_get( $id, 'posts' ), 'Sentinel: the post is cached.' );

		$this->run_update_date( $id, ReplaceController::TIME_UPDATEALL, '2018-08-08 08:08:08' );

		$this->assertFalse( wp_cache_get( $id, 'posts' ) );
		$this->assertSame( '2018-08-08 08:08:08', get_post( $id )->post_date );
	}

	/*
	 * removeCurrent().
	 */

	private function size_files( $id ) {
		$meta  = wp_get_attachment_metadata( $id );
		$dir   = dirname( get_attached_file( $id ) );
		$files = array();
		foreach ( $meta['sizes'] as $size ) {
			$files[] = $dir . '/' . $size['file'];
		}
		return $files;
	}

	public function test_remove_current_deletes_the_main_file_and_the_thumbnails() {
		$id     = $this->upload_large();
		$main   = get_attached_file( $id );
		$thumbs = $this->size_files( $id );
		$this->assertNotEmpty( $thumbs, 'Sentinel: thumbnails were generated.' );
		foreach ( $thumbs as $thumb ) {
			$this->assertFileExists( $thumb );
		}
		$controller = new ReplaceController( $id );

		$this->call( $controller, 'removeCurrent' );

		$this->assertFileDoesNotExist( $main );
		foreach ( $thumbs as $thumb ) {
			$this->assertFileDoesNotExist( $thumb );
		}
		$this->assertNotEmpty( wp_get_attachment_metadata( $id ), 'The metadata is left in place.' );
	}

	public function test_remove_current_fires_the_after_remove_action() {
		$id = $this->upload();
		update_post_meta( $id, '_wp_attachment_backup_sizes', array( 'full-orig' => array( 'file' => 'emr-none.jpg' ) ) );
		$meta       = wp_get_attachment_metadata( $id );
		$controller = new ReplaceController( $id );
		$controller->setupParams( $this->params() );
		$this->add_hook( 'emr_after_remove_current', $this->record( 'removed' ), 10, 5 );

		$this->call( $controller, 'removeCurrent' );

		$this->assertCount( 1, $this->events );
		list( $post_id, $passed_meta, $backup, $source, $target ) = $this->events[0][1];
		$this->assertSame( $id, $post_id );
		$this->assertSame( $meta, $passed_meta );
		$this->assertSame( array( 'full-orig' => array( 'file' => 'emr-none.jpg' ) ), $backup );
		$this->assertSame( $controller->getSourceFile(), $source );
		$this->assertSame( $this->prop( $controller, 'targetFile' ), $target );
	}

	public function test_remove_current_hard_unlinks_an_attached_file_left_over() {
		$id     = $this->upload_large();
		$main   = get_attached_file( $id );
		$thumbs = $this->size_files( $id );
		// Block every regular deletion, like a plugin that protects shared files.
		$this->add_hook( 'wp_delete_file', '__return_empty_string' );
		$controller = new ReplaceController( $id );

		$this->call( $controller, 'removeCurrent' );

		$this->assertFileDoesNotExist( $main );
		$this->assertFileExists( $thumbs[0], 'The blocked thumbnails stay.' );
		foreach ( $thumbs as $thumb ) {
			$this->files[] = $thumb;
		}
	}

	public function test_remove_current_removes_the_scaled_attached_file() {
		list( $id, $orig, $scaled ) = $this->scaled_attachment();
		$controller                 = new ReplaceController( $id );

		$this->call( $controller, 'removeCurrent' );

		$this->assertFileDoesNotExist( $orig );
		$this->assertFileDoesNotExist( $scaled );
	}

	/*
	 * run().
	 */

	private function replace_controller( $id, array $overrides ) {
		$controller = new ReplaceController( $id );
		$this->assertTrue( $controller->setupParams( $this->params( $overrides ) ), 'Sentinel: setupParams() resolved a target.' );
		return $controller;
	}

	public function test_run_replace_mode_writes_the_new_bytes_in_place_and_regenerates_metadata() {
		$id     = $this->upload();
		$source = get_attached_file( $id );
		$tmp    = $this->tmp_small_jpeg( 120, 90 );
		$md5    = md5_file( $tmp );
		$this->assertNotSame( md5_file( $source ), $md5 );
		$controller = $this->replace_controller( $id, array( 'uploadFile' => $tmp ) );

		$result = $controller->run();

		$this->assertTrue( $result );
		$this->assertNull( $controller->returnLastError() );
		$this->assertSame( $source, get_attached_file( $id ) );
		$this->assertSame( $md5, md5_file( $source ) );
		$meta = wp_get_attachment_metadata( $id );
		$this->assertSame( 120, $meta['width'] );
		$this->assertSame( 90, $meta['height'] );
		$this->assertFileDoesNotExist( $tmp, 'The temporary upload is removed.' );
	}

	public function test_run_fires_the_replace_actions_in_order() {
		$id         = $this->upload();
		$controller = $this->replace_controller( $id, array( 'uploadFile' => $this->tmp_small_jpeg() ) );
		$source_url = $controller->getSourceUrl();
		$this->add_hook( 'wp_handle_replace', $this->record( 'wp_handle_replace' ) );
		$this->add_hook( 'emr/converter/prevent-offload', $this->record( 'prevent-offload' ) );
		$this->add_hook( 'emr/converter/prevent-offload-off', $this->record( 'prevent-offload-off' ) );
		$this->add_hook( 'wp_generate_attachment_metadata', $this->record( 'generate-metadata' ) );
		$this->add_hook( 'enable-media-replace-upload-done', $this->record( 'upload-done' ), 10, 3 );

		$controller->run();

		$this->assertSame( array( 'wp_handle_replace', 'prevent-offload', 'generate-metadata', 'prevent-offload-off', 'upload-done' ), $this->event_names() );
		$this->assertSame( array( array( 'post_id' => $id ) ), $this->events[0][1] );
		$this->assertSame( array( $id ), $this->events[1][1] );
		$this->assertSame( array( $id ), $this->events[3][1] );
		$this->assertSame( array( wp_get_attachment_url( $id ), $source_url, $id ), $this->events[4][1] );
	}

	public function test_run_applies_wp_handle_upload_with_sideload() {
		$id         = $this->upload();
		$controller = $this->replace_controller( $id, array( 'uploadFile' => $this->tmp_small_jpeg() ) );
		$this->add_hook( 'wp_handle_upload', $this->record( 'wp_handle_upload' ), 10, 2 );

		$controller->run();

		$this->assertSame( array( 'wp_handle_upload' ), $this->event_names() );
		list( $upload, $context ) = $this->events[0][1];
		$this->assertSame( 'sideload', $context );
		$this->assertSame(
			array(
				'file' => get_attached_file( $id ),
				'url'  => wp_get_attachment_url( $id ),
				'type' => 'image/jpeg',
			),
			$upload
		);
	}

	public function test_run_honours_a_file_changed_by_wp_handle_upload() {
		$id      = $this->upload();
		$dir     = dirname( get_attached_file( $id ) );
		$changed = $dir . '/emr-converted-' . strtolower( wp_generate_password( 6, false, false ) ) . '.png';
		$this->files[] = $changed;
		$this->add_hook(
			'wp_handle_upload',
			function ( $upload ) use ( $changed ) {
				copy( dirname( __DIR__ ) . '/fixtures/codeispoetry.png', $changed );
				$upload['file'] = $changed;
				return $upload;
			}
		);
		$controller = $this->replace_controller( $id, array( 'uploadFile' => $this->tmp_small_jpeg() ) );

		$this->assertTrue( $controller->run() );

		$this->assertSame( $changed, get_attached_file( $id ) );
		$this->assertSame( $changed, $this->prop( $controller, 'targetFile' )->getFullPath() );
		$this->assertSame( 'image/png', get_post_mime_type( $id ) );
	}

