		$old_url = wp_get_attachment_url( $id );
		$post_id = self::factory()->post->create( array( 'post_content' => '<img src="' . $old_url . '" />' ) );
		$name    = 'emr-content-' . strtolower( wp_generate_password( 6, false, false ) ) . '.jpg';
		$controller = $this->replace_controller(
			$id,
			array(
				'replace_type' => 'replace_and_search',
				'new_filename' => $name,
				'uploadFile'   => $this->tmp_small_jpeg(),
