	/**
	 * run() sets ERROR_COPY_FAILED when the uploaded file cannot be copied
	 * to the target, but carries on and returns true, so a caller that only
	 * checks the return value shows the success screen for an attachment
	 * that now has no file. It should return false (or the callers should
	 * check returnLastError()).
	 *
	 * The attachment is a text file and its file is removed before the
	 * controller is created, so the run reaches the end: with an image the
	 * metadata generation reads the missing file (a getimagesize() warning
	 * under WP_DEBUG), and with an existing source the copy failure is not
	 * even recorded (see the next two tests).
	 *
	 * How to recognise the fix: run() returns false and the assertTrue
	 * fails.
	 */
	public function test_run_returns_true_after_copy_failed_pinned_for_deferred_fix() {
		$id      = $this->upload( 'test-vector.svg', 'emr-copyfail.txt' );
		$missing = get_temp_dir() . 'emr-missing-upload-' . wp_generate_password( 8, false, false );
		$this->assertFileDoesNotExist( $missing );
		unlink( get_attached_file( $id ) );
		$controller = $this->replace_controller( $id, array( 'uploadFile' => $missing ) );

		$result = $controller->run();

		$this->assertSame( ReplaceController::ERROR_COPY_FAILED, $controller->returnLastError() );
		$this->assertFileDoesNotExist( get_attached_file( $id ) );
		$this->assertTrue( $result, 'Pinned: run() reports success.' );
	}

	/**
	 * When the copy fails while the source existed, run() still restores
	 * the permission snapshot with chmod() on the target path, which no
	 * longer exists (removeCurrent() deleted it), and PHP raises a
	 * "No such file or directory" warning. The chmod() should only run when
	 * the target exists.
	 *
	 * How to recognise the fix: no warning is raised, run() completes and
	 * the expectWarning() fails.
	 */
	public function test_run_chmods_a_missing_target_after_copy_failed_pinned_for_deferred_fix() {
		$id      = $this->upload();
		$missing = get_temp_dir() . 'emr-missing-upload-' . wp_generate_password( 8, false, false );
		$controller = $this->replace_controller( $id, array( 'uploadFile' => $missing ) );
		$this->assertFileExists( get_attached_file( $id ), 'Sentinel: the source exists before the run.' );

		$warning = null;
		try {
			$controller->run();
		} catch ( \PHPUnit\Framework\Error\Warning $e ) {
			$warning = $e;
		}

		$this->assertInstanceOf( \PHPUnit\Framework\Error\Warning::class, $warning, 'Pinned: run() raises a warning.' );
		$this->assertMatchesRegularExpression( '/chmod\(\).*No such file or directory/', $warning->getMessage() );
		$this->assertSame( realpath( dirname( __DIR__, 2 ) . '/classes/Controller/ReplaceController.php' ), realpath( $warning->getFile() ) );
	}

	/**
	 * In MODE_REPLACE, run() asks the target file object whether the target
	 * exists after a failed copy. That object was created before
	 * removeCurrent() deleted the file, and its exists() status is cached
	 * from that moment (getFileDir() triggers the lookup), so it still
	 * answers true: "Copy declared failed, but target available" is logged
	 * and ERROR_COPY_FAILED is never set, although the attachment no longer
	 * has a file. The check should use exists(true) or a fresh object.
	 *
	 * The run then stops on the chmod() warning pinned above; the decision
	 * about the error is made before it.
	 *
	 * How to recognise the fix: returnLastError() is ERROR_COPY_FAILED (22)
	 * and the assertNull fails.
	 */
	public function test_copy_failure_over_an_existing_source_is_not_recorded_pinned_for_deferred_fix() {
		$id      = $this->upload();
		$source  = get_attached_file( $id );
		$missing = get_temp_dir() . 'emr-missing-upload-' . wp_generate_password( 8, false, false );
		$controller = $this->replace_controller( $id, array( 'uploadFile' => $missing ) );
		$this->assertFileExists( $source, 'Sentinel: the source exists before the run.' );

		try {
			$controller->run();
		} catch ( \PHPUnit\Framework\Error\Warning $e ) {
			unset( $e );
		}

		$this->assertFileDoesNotExist( $source, 'The attachment has no file any more.' );
		$this->assertNull( $controller->returnLastError(), 'Pinned: the failed copy is not recorded.' );
	}

	/**
	 * run() sets ERROR_UPDATE_POST when wp_update_post() returns a WP_Error
	 * in search-replace mode, then continues and returns true. It should
	 * return false so the error view is shown.
	 *
	 * How to recognise the fix: run() returns false and the assertTrue
	 * fails.
	 */
	public function test_run_returns_true_after_update_post_failed_pinned_for_deferred_fix() {
		$id = $this->upload();
		$this->add_hook( 'wp_insert_post_empty_content', '__return_true' );
		$controller = $this->replace_controller(
			$id,
			array(
				'replace_type' => 'replace_and_search',
				'new_filename' => 'emr-upd-' . strtolower( wp_generate_password( 6, false, false ) ) . '.jpg',
				'uploadFile'   => $this->tmp_small_jpeg(),
			)
		);

		$result = $controller->run();

		$this->assertSame( ReplaceController::ERROR_UPDATE_POST, $controller->returnLastError() );
		$this->assertTrue( $result, 'Pinned: run() reports success.' );
	}
